# 194 - link YouTube veloci
def _spenta():
    try:
        from moduli.database import Database
        return str(Database.get_config('patch_194', '1')) == '0'
    except Exception:
        return False


VER = 2
_FUNZIONI = ''
_SERVER = ''


def _server_nuovo():
    import os, base64, zlib
    d = os.path.join(os.environ.get('LOCALAPPDATA') or os.path.expanduser('~'), 'KaraDom', 'yt_server')
    p = os.path.join(d, 'ytdlp_local_server.py')
    dati = zlib.decompress(base64.b64decode(_SERVER))
    try:
        if not os.path.exists(p) or open(p, 'rb').read() != dati:
            os.makedirs(d, exist_ok=True)
            with open(p + '.tmp', 'wb') as f:
                f.write(dati)
            os.replace(p + '.tmp', p)
        return p
    except Exception:
        return None


def apply():
    if _spenta():
        return False
    import sys
    m = sys.modules.get('moduli.youtube_local')
    if m is None:
        try:
            from moduli import youtube_local as m
        except Exception:
            return False
    if getattr(m, '_patch_194_ver', None) == VER:
        return True
    import os, zlib, base64
    exec(compile(zlib.decompress(base64.b64decode(_FUNZIONI)).decode('utf-8'), 'youtube_local_194', 'exec'), m.__dict__)
    vecchio = getattr(m, '_server_script_194_o', None) or m._server_script
    m._server_script_194_o = vecchio

    def _server_script():
        s = vecchio()
        try:
            if s and b'SERVER_REV = 3' in open(s, 'rb').read():
                return s
        except Exception:
            pass
        return _server_nuovo() or s
    m._server_script = _server_script
    m._patch_194_ver = VER
    try:
        import threading
        threading.Thread(target=m._ensure_server, daemon=True).start()
    except Exception:
        pass
    return True
